// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= address(c).balance + 1 ether);
        vm.deal(address(this), amount);
        // deposit
        c.deposit{value: amount}();
        // capture balance before migrateTo
        uint256 balanceBefore = address(c).balance;
        address to = address(0x1234);
        uint256 toBalanceBefore = to.balance;
        // call migrateTo
        c.migrateTo(to);
        // rule: after migrateTo, the contract balance is 0 and the target receives the full balance
        assertTrue(address(c).balance == 0 && to.balance == toBalanceBefore + balanceBefore);
    }
}

